-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_global_epi AS WITH op AS (SELECT research_id, surgery_episode_id AS op_epi, CAST(surgery_date_native AS DATE) AS sd FROM main.canonical_operative_events_v1 WHERE (surgery_date_native IS NOT NULL))SELECT p.*, op.op_epi AS surgery_episode_id_global, CASE  WHEN (((op.op_epi IS NOT NULL) AND (p.surgery_episode_id = op.op_epi))) THEN ('already_match') WHEN ((op.op_epi IS NOT NULL)) THEN ('op_rebind') WHEN ((CAST(p.surgery_date AS DATE) IS NULL)) THEN ('no_date') ELSE 'md5_fallback' END AS surgery_episode_uid_source, ((op.op_epi IS NOT NULL) AND (p.surgery_episode_id IS DISTINCT FROM op.op_epi)) AS op05_rebind_applied_flag FROM main.canonical_path_malignant_events_v1 AS p LEFT JOIN op ON (((op.research_id = p.research_id) AND (op.sd = CAST(p.surgery_date AS DATE))));
